from version_compare import latest_version, meets_minimum


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """Return the highest version in `versions` that is at least `minimum`, or None if none qualify."""
    compatible = [v for v in versions if meets_minimum(v, minimum)]
    return latest_version(compatible)

import asyncio
from async_bridge import run_sync


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently, returning results in input order.
    Coroutines not finished within `seconds` are cancelled and replaced by None.
    Can be called repeatedly from synchronous code with no running event loop."""
    async def _main():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        await asyncio.gather(*pending, return_exceptions=True)
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                results.append(None)
        return results

    return run_sync(_main())

from web_utils import parse_content_type, content_charset, image_type

def describe_upload(content_type: str, data: bytes) -> dict:
    """
    Given a Content-Type header value and the first bytes of the body,
    return a dict with keys:
      - "mime": lower-cased media type without parameters,
      - "charset": lower-cased charset parameter or None if not present,
      - "image": "png", "jpeg", "gif" or None detected from data signature bytes.
    """
    mime, params = parse_content_type(content_type)
    charset = params.get('charset')
    if charset is not None:
        charset = charset.lower()
    else:
        charset = None
    img_type = image_type(data)
    # Only keep png, jpeg, gif or None for image key
    if img_type not in ('png', 'jpeg', 'gif'):
        img_type = None
    return {"mime": mime, "charset": charset, "image": img_type}

import asyncio
from asyncio import Semaphore, TimeoutError as AsyncTimeoutError

def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently from synchronous code, returning their results in input order.
    Any coroutine not finishing within `seconds` is cancelled and its result is None.
    Can be called repeatedly in the same process.
    """
    if not isinstance(coros, list):
        raise ValueError("coros must be a list of coroutines")
    for c in coros:
        if not asyncio.iscoroutine(c):
            raise ValueError(f"all inputs must be coroutines, got {type(c)}")

    async def _run_with_deadline(coros, timeout):
        # Wrap each coro with asyncio.wait_for(timeout) to impose per-task timeout
        # But we want to cancel tasks that exceed timeout and return None for them
        # Using wait_for would raise TimeoutError; we catch and return None instead
        async def run_coro(coro):
            try:
                return await asyncio.wait_for(coro, timeout=timeout)
            except AsyncTimeoutError:
                return None

        tasks = [asyncio.create_task(run_coro(c)) for c in coros]
        results = await asyncio.gather(*tasks)
        return results

    return asyncio.run(_run_with_deadline(coros, seconds))

