def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently from synchronous code, returning their results in input order.
    Any coroutine not finished within `seconds` is cancelled and its result is None.
    Works when called repeatedly in the same process.
    """
    async def run_all_with_timeout():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Gather results for done tasks
        results = [None] * len(tasks)
        # For done tasks, get result or None if exception (including CancelledError)
        for i, task in enumerate(tasks):
            if task in done:
                try:
                    results[i] = task.result()
                except Exception:
                    results[i] = None
            else:
                results[i] = None
        return results

    return asyncio.run(run_all_with_timeout())

import asyncio

def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently from synchronous code, returning their results in input order.
    Any coroutine not finished within `seconds` is cancelled and its result is None.
    Works correctly when called repeatedly in the same process.
    """
    async def runner():
        tasks = [asyncio.create_task(c) for c in coros]
        try:
            done, pending = await asyncio.wait(tasks, timeout=seconds)
            # Cancel all pending tasks
            for task in pending:
                task.cancel()
            # Await cancellation completion
            for task in pending:
                try:
                    await task
                except asyncio.CancelledError:
                    pass
            # Collect results in input order, None for cancelled or errored tasks
            results = []
            for task in tasks:
                if task.done():
                    try:
                        results.append(task.result())
                    except Exception:
                        # If task raised, treat as None result
                        results.append(None)
                else:
                    # Not done (should not happen after cancellation), treat as None
                    results.append(None)
            return results
        finally:
            # Just in case, cancel any remaining tasks
            for task in tasks:
                if not task.done():
                    task.cancel()

    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(runner())
    finally:
        asyncio.set_event_loop(None)
        loop.close()
